import http, { Server } from 'node:http';
import path from 'node:path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar, { FSWatcher } from 'chokidar';
import { BuildOptions, buildSite } from './index';

export interface DevServerOptions extends BuildOptions { port?: number; host?: string; }
export interface DevServer { server: Server; watcher: FSWatcher; webSocketServer: WebSocketServer; close: () => Promise<void>; }

const contentTypes: Record<string, string> = {
  '.css': 'text/css; charset=utf-8', '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8',
  '.svg': 'image/svg+xml', '.txt': 'text/plain; charset=utf-8'
};

function injectLiveReload(html: string): string {
  const script = `<script>(function(){var socket=new WebSocket((location.protocol==='https:'?'wss://':'ws://')+location.host+'/__ssg_reload');socket.onmessage=function(event){if(event.data==='reload')location.reload();};socket.onclose=function(){setTimeout(function(){location.reload();},1000);};})();</script>`;
  return /<\/body\s*>/i.test(html) ? html.replace(/<\/body\s*>/i, `${script}</body>`) : `${html}${script}`;
}

